def dehydrate_point(value):
    """Dehydrate a Point object into a serializable dict.

    Supports objects with ``x`` and ``y`` attributes (e.g., custom Point classes)
    or sequence-like objects representing ``(x, y)`` coordinates.
    """
    if value is None:
        return None
    # Try attribute access first (common for custom Point classes or shapely points)
    if hasattr(value, "x") and hasattr(value, "y"):
        return {"x": getattr(value, "x"), "y": getattr(value, "y")}
    # Fallback: treat as a sequence like (x, y)
    try:
        return {"x": value[0], "y": value[1]}
    except (TypeError, IndexError) as exc:
        raise TypeError(
            f"Cannot dehydrate value of type {type(value).__name__}: "
            f"expected a point-like object with x and y attributes or a sequence"
        ) from exc

