def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    import functools
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Generate the cache key from the function arguments
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                # If the key function fails, fall back to normal execution
                return func(*args, **kwargs)

            # Attempt to return a cached value
            try:
                return cache[k]
            except Exception:
                # Key either missing or cache access failed
                pass

            # Acquire the lock if one is provided
            if lock:
                # Support simple lock objects with acquire/release
                if hasattr(lock, "acquire") and hasattr(lock, "release"):
                    lock.acquire()
                    try:
                        # Double‑check after acquiring the lock
                        try:
                            return cache[k]
                        except Exception:
                            pass
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                    finally:
                        lock.release()
                else:
                    # Assume lock is a context manager
                    with lock:
                        try:
                            return cache[k]
                        except Exception:
                            pass
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
            else:
                # No lock: compute and cache the result
                result = func(*args, **kwargs)
                cache[k] = result
                return result

        return wrapper
    return decorator

