    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0 or None")

    def decorating_function(user_function):
        cache = collections.OrderedDict()
        hits = misses = 0

        def make_key(args, kwargs):
            # Convert kwargs to a tuple of sorted items
            if kwargs:
                kwargs_items = tuple(sorted(kwargs.items()))
            else:
                kwargs_items = ()
            if typed:
                key = args + kwargs_items + tuple(type(v) for v in args) + tuple((k, type(v)) for k, v in kwargs.items())
            else:
                key = args + kwargs_items
            return key

        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
            try:
                result = cache[key]
                hits += 1
                # Move key to the end to mark it as recently used
                cache.move_to_end(key)
                return result
            except KeyError:
                misses += 1
                result = user_function(*args, **kwargs)
                # Insert into cache
                cache[key] = result
                if len(cache) > maxsize:
                    # popitem(last=False) removes first item (least recently used)
                    cache.popitem(last=False)
                return result

