def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = type(self).__name__
    # Remove known suffixes
    if cls_name.endswith('Py'):
        target_name = cls_name[:-2]
    elif cls_name.endswith('Fallback'):
        target_name = cls_name[:-8]
    else:
        target_name = cls_name
    # Retrieve the class from the current module's global namespace
    return globals().get(target_name)

