def to_csv(self, separator=",", header=None):
        """
        .. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
            Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        # Helper to convert an element to string if it is iterable (but not a string)
        def _join_parts(part):
            from collections.abc import Iterable
            if isinstance(part, str):
                return part
            if isinstance(part, Iterable):
                return separator.join(str(item) for item in part)
            return str(part)

        lines = []
        if header is not None:
            lines.append(str(header))

        # Assume the graph stores points in an iterable of (coord, value) pairs.
        for item in getattr(self, "points", []):
            if isinstance(item, tuple) and len(item) == 2:
                coord, value = item
            else:
                # If points are stored directly as (coord, value) objects
                # try to access attributes
                try:
                    coord = getattr(item, "coord")
                    value = getattr(item, "value")
                except AttributeError:
                    # Fallback: treat the whole item as coordinate with no value
                    coord = item
                    value = None

            coord_str = _join_parts(coord)
            if value is None:
                line = coord_str
            else:
                value_str = _join_parts(value)
                # If value string contains the separator, avoid double separation
                if separator in value_str:
                    # Already joined by separator, just append
                    line = f"{coord_str}{separator}{value_str}"
                else:
                    line = f"{coord_str}{separator}{value_str}"
            lines.append(line)

        return "\n".join(lines)

