def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Determine the name of the error attribute for the coordinate
    err_attr = f"{coord_name}_err"
    if not hasattr(self, err_attr):
        raise ValueError(
            f"No error attribute '{err_attr}' found for coordinate '{coord_name}'."
        )
    err = getattr(self, err_attr)

    # Try to convert to a NumPy array for vectorized operations
    try:
        err_arr = np.array(err, dtype=float)
        # Use NaN as the missing value sentinel
        mask = ~np.isnan(err_arr)
        return np.where(mask)[0]
    except Exception:
        # Fallback for non‑NumPy sequences (list, tuple, etc.)
        indices = []
        for idx, val in enumerate(err):
            if val is None:
                continue
            if isinstance(val, float) and np.isnan(val):
                continue
            indices.append(idx)
        return np.array(indices)

