def _update_context(self, context):
    # Determine list of fields belonging to this graph.
    if hasattr(self, "data") and isinstance(self.data, dict):
        fields = list(self.data.keys())
    elif hasattr(self, "columns") and isinstance(self.columns, (list, tuple)):
        fields = list(self.columns)
    elif hasattr(self, "fields") and isinstance(self.fields, (list, tuple)):
        fields = list(self.fields)
    else:
        fields = []

    # Ensure the top‑level error sub‑context exists.
    errors = context.get("error", {})
    # Iterate over fields and capture those that represent errors.
    for idx, field in enumerate(fields):
        if not isinstance(field, str):
            continue
        if not field.startswith("error_"):
            continue
        # Extract the part after 'error_'. We expect patterns like
        # error_x, error_y_low, error_z_high, or any custom name.
        suffix = field[6:]  # everything after 'error_'
        parts = suffix.split("_", 1)
        if len(parts) == 2:
            base, err_type = parts
            key = f"{base}_{err_type}"
        else:
            base = parts[0]
            key = base
        # Map coordinate names to simplified axes if applicable.
        if base.lower() in ("x", "y", "z"):
            key = f"{base.lower()}_{err_type}" if len(parts) == 2 else base.lower()
        errors[key] = {"index": idx}
    context["error"] = errors

    # Preserve existing values in context.value; we do not modify them.
    return

