def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is itself a FillRequest, it's valid.
    if isinstance(seq, FillRequest):
        return True

    # If seq is a Source sequence, it's invalid.
    if isinstance(seq, Source):
        return False

    # If seq is iterable, check its elements.
    try:
        iterator = iter(seq)
    except TypeError:
        # Not iterable and not a FillRequest, so invalid.
        return False

    # Check for the presence of any Source element (invalid) or at least one FillRequest element (valid).
    has_fill = False
    for item in iterator:
        if isinstance(item, Source):
            return False
        if isinstance(item, FillRequest):
            has_fill = True

    return has_fill

