def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Convert coordinate to a tuple for indexing
        try:
            coord = tuple(coord)
        except Exception:
            coord = (coord,)

        # Determine edges and ensure they are iterable
        if isinstance(self.edges, (list, tuple)):
            edges = self.edges
        else:
            edges = [self.edges]

        # Number of dimensions must match
        if len(coord) != len(edges):
            return

        bin_indices = []
        for c, edge in zip(coord, edges):
            # Find bin index: edge[i] <= c < edge[i+1]
            idx = np.searchsorted(edge, c, side='right') - 1
            # Check if coordinate is inside the histogram range
            if idx < 0 or idx >= len(edge) - 1:
                return
            bin_indices.append(idx)

        # Add weight to the appropriate bin
        try:
            self.bins[tuple(bin_indices)] += weight
        except Exception:
            # Support nested list structure for bins
            indices_iter = iter(bin_indices)
            ref = self.bins
            try:
                while True:
                    i = next(indices_iter)
                    if not isinstance(next(indices_iter, None), (int,)):
                        ref = ref[i]
            except StopIteration:
                ref[i] += weight
