def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary by replacing all non-structure
    values with ``None`` while preserving the shape of the ``manifest_dict``.
    When ``first_level`` is ``True`` copying of identifying fields (``apiVersion`` and
    ``kind``) is performed from the original manifest.

    Args:
        manifest_dict (dict): Input partial Kubernetes resource.
        first_level (bool, optional): If ``True``, indicates that the dictionary
            represents the top‑level schema of a resource.

    Returns:
        dict: Default observer schema dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    result = {}
    for key, value in manifest_dict.items():
        # Keep dictionary structure
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Replace lists by a list of None placeholders matching original length
        elif isinstance(value, list):
            result[key] = [None] * len(value)
        # Replace primitives by None (unless top-level identifying fields)
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

