def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Update a list‐type last_applied_manifest from a partial Kubernetes
    response recursively, based on an observer_schema describing the shape of
    the data.
    """
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if response is None:
        return
    # Ensure response is a list
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    # Ensure observer_schema aligns with response
    for idx, resp_item in enumerate(response):
        # Expand the target list if needed
        while len(last_applied_manifest) <= idx:
            # guess an appropriate placeholder based on schema
            schema_item = None
            if isinstance(observer_schema, list) and idx < len(observer_schema):
                schema_item = observer_schema[idx]
            if isinstance(schema_item, dict):
                last_applied_manifest.append({})
            elif isinstance(schema_item, list):
                last_applied_manifest.append([])
            else:
                last_applied_manifest.append({})
        # now we have an element at idx
        target_item = last_applied_manifest[idx]
        schema_item = None
        if isinstance(observer_schema, list) and idx < len(observer_schema):
            schema_item = observer_schema[idx]
        # If schema says a dict, recurse into dict logic
        if isinstance(schema_item, dict):
