        """Check all digests in manifest that are needed are present and used."""
        # Build a set of digests that are present in the manifest
        if isinstance(manifest_files, dict):
            digests_in_manifest = set(manifest_files.keys())
        else:
            # Assume a list of dicts with a 'hash' key
            digests_in_manifest = {entry.get("hash") for entry in manifest_files if isinstance(entry, dict)}

        digests_needed = set(digests_used)

        # Digests that are required but missing from the manifest
        missing = digests_needed - digests_in_manifest
        if missing:
            raise ValueError(f"Missing digests in manifest: {sorted(missing)}")

        # Digests that are present in the manifest but never used
        unused = digests_in_manifest - digests_needed
        if unused:
            raise ValueError(f"Unexpected digests present in manifest but not used: {sorted(unused)}")

