def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if prior is None:
            raise ValueError("prior must not be None")

        # Ensure the prior object is of the same type
        if not isinstance(prior, type(self)):
            raise TypeError(
                f"prior must be an instance of {type(self).__name__}, "
                f"got {type(prior).__name__}"
            )

        # Validate that both objects expose a comparable version attribute
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise AttributeError(
                "Both self and prior must have a 'version' attribute to compare"
            )
        if not isinstance(self.version, (int, float)):
            raise TypeError(f"self.version must be numeric, got {type(self.version).__name__}")
        if not isinstance(prior.version, (int, float)):
            raise TypeError(f"prior.version must be numeric, got {type(prior.version).__name__}")

        if prior.version >= self.version:
            raise ValueError(
                f"prior.version ({prior.version}) must be less than current version ({self.version})"
            )

        # If timestamps are available, ensure prior is not newer
        if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
            if not isinstance(self.timestamp, (int, float)):
                raise TypeError(f"self.timestamp must be numeric, got {type(self.timestamp).__name__}")
            if not isinstance(prior.timestamp, (int, float)):
                raise TypeError(f"prior.timestamp must be numeric, got {type(prior.timestamp).__name__}")
            if prior.timestamp > self.timestamp:
                raise ValueError(
                    f"prior.timestamp ({prior.timestamp}) must be <= current timestamp ({self.timestamp})"
                )

        # If all checks pass, consider the prior version valid
        return True

