def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # The fixity block is expected to be a list of entries.
    if not isinstance(fixity, list):
        raise ValueError("The 'fixity' block must be a list of entries.")

    # Ensure we have a set for efficient lookup.
    manifest_set = set(manifest_files)

    for idx, entry in enumerate(fixity, start=1):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry #{idx} is not a dict.")

        # Each entry must contain the key 'file'
        if 'file' not in entry:
            raise ValueError(f"Fixity entry #{idx} is missing the 'file' key.")

        file_path = entry['file']
        if file_path not in manifest_set:
            raise ValueError(
                f"Fixity entry #{idx} references file '{file_path}' "
                f"which is not present in the manifest."
            )

        # Check that a checksum dict is provided
        if 'checksum' not in entry:
            raise ValueError(f"Fixity entry #{idx} is missing the 'checksum' key.")
        checksum = entry['checksum']
        if not isinstance(checksum, dict):
            raise ValueError(f"Checksum for entry #{idx} must be a dict.")

        # Check that the checksum dict contains both 'algorithm' and 'value'
        if 'algorithm' not in checksum or 'value' not in checksum:
            raise ValueError(
                f"Checksum for entry #{idx} must include both 'algorithm' and 'value' keys."
            )

    # If all checks pass, validation succeeds.
    return True

