def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format_val(v, cur_indent):
        if hasattr(v, 'pretty') and callable(v.pretty):
            return v.pretty(cur_indent, debug)
        if isinstance(v, dict):
            lines = ["{"]
            for k in sorted(v):
                val_str = _format_val(v[k], cur_indent + 4)
                lines.append(" " * (cur_indent + 4) + f"{repr(k)}: {val_str}")
            lines.append(" " * cur_indent + "}")
            return "\n".join(lines)
        if isinstance(v, (list, tuple, set)):
            type_name = type(v).__name__
            lines = [f"{type_name}(["]
            for item in v:
                val_str = _format_val(item, cur_indent + 4)
                lines.append(" " * (cur_indent + 4) + val_str)
            lines.append(" " * cur_indent + "])")
            return "\n".join(lines)
        return repr(v) + (f" ({type(v).__name__})" if debug else "")
    lines = [f"{self.__class__.__name__}("]
    for attr in sorted(self.__dict__):
        val = getattr(self, attr)
        val_str = _format_val(val, indent + 4)
        lines.append(" " * (indent + 4) + f"{attr}={val_str},")
    lines.append(" " * indent + ")")
    return "\n".join(lines)

