def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the storage hierarchy.
    # Assume self.iter_objects() yields each object (could be a file, directory,
    # or any storage entity that implements `validate` and `check_digest`).
    for obj in self.iter_objects():
        num_objects += 1
        is_valid = True

        # Validate the object structure or metadata if requested.
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"WARNING: Validation failed for {obj}: {exc}")
                else:
                    raise RuntimeError(f"Validation failed for {obj}: {exc}") from exc

        # Check the digest/hash of the object if requested.
        if check_digests:
            try:
                if hasattr(obj, 'check_digest'):
                    obj.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"WARNING: Digest check failed for {obj}: {exc}")
                else:
                    raise RuntimeError(f"Digest check failed for {obj}: {exc}") from exc

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

