def _replace_url_args(url, url_args):
    """
    Replace any custom string URL items with values in args.
    Placeholders are expected to be in the form {placeholder}.
    If a placeholder is not found in url_args, it will be left unchanged.
    """
    if not url_args:
        return url

    import re

    # Pattern matches {placeholder} where placeholder is a word (letters, digits, underscore)
    placeholder_pattern = re.compile(r'\{(\w+)\}')

    def replace_match(match):
        key = match.group(1)
        # Use the value from url_args if it exists; otherwise keep the original placeholder.
        return str(url_args.get(key, match.group(0)))

    return placeholder_pattern.sub(replace_match, url)

