def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from the matcher
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 2:
            name, default = matcher
        elif len(matcher) == 1:
            name = matcher[0]
            default = None
        else:
            raise ValueError(f"Matcher must contain 1 or 2 elements, got {len(matcher)}: {matcher}")
    elif hasattr(matcher, 'name') and hasattr(matcher, 'default'):
        name, default = matcher.name, matcher.default
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    # Fetch the environment variable
    value = os.environ.get(name)

    # If undefined and default is not provided, raise an error
    if value is None:
        if default is None:
            raise KeyError(f"Environment variable '{name}' is not set and no default value was provided.")
        return default

    return value

