def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import yaml
    logger = logging.getLogger(__name__)
    configs = {}
    error_records = []

    def _resolve_env_strings(obj):
        if isinstance(obj, str):
            # Replace occurrences of ${VAR} with environment variable value
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            return pattern.sub(lambda m: os.getenv(m.group(1), m.group(0)), obj)
        elif isinstance(obj, dict):
            return {k: _resolve_env_strings(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_strings(v) for v in obj]
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                data = yaml.safe_load(f) or {}
            if not isinstance(data, dict):
                raise ValueError("Configuration must be a dictionary")
            if resolve_env:
                data = _resolve_env_strings(data)
            if overrides:
                data.update(overrides)
            configs[filename] = data
        except Exception as exc:
            # Create a LogRecord with ERROR level
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__),
            )
            error_records.append(record)
    return configs, error_records

