@classmethod
    def from_raw_values(cls, values):
        """
        Create a Bookmarks instance from an iterable of raw bookmark string values.
        The method expects `values` to be an Iterable[str] (e.g. a list or set of
        ASCII bookmark strings).  It constructs a new instance, then populates it
        by adding each bookmark value individually.  Any leading or trailing
        whitespace is stripped from each value.

        This method is mainly for deserialising bookmark data that has been stored
        or transmitted as raw strings.

        :param values: Iterable containing raw bookmark strings.
        :type values: Iterable[str]
        :return: A new Bookmarks instance containing the provided bookmarks.
        :rtype: Bookmarks
        """
        # Create an empty Bookmarks instance; assumes default ctor exists.
        instance = cls()

        # Iterate over the provided values, ensuring each is added correctly.
        for raw_value in values:
            # Basic type guard – skip None or non‑string items silently.
            if raw_value is None:
                continue
            if not isinstance(raw_value, str):
                # Convert to string if appropriate; otherwise skip.
                try:
                    raw_value = str(raw_value)
                except Exception:
                    continue
            cleaned = raw_value.strip()
            if cleaned:
                # Prefer to use an `add` method if the class offers one,
                # otherwise fall back to direct attribute manipulation.
                if hasattr(instance, "add") and callable(instance.add):
                    instance.add(cleaned)
                else:
                    # Guess plausible attribute names that hold the internal set/list
                    for attr in ("bookmarks", "entries", "items", "data"):
                        if hasattr(instance, attr):
                            container = getattr(instance, attr)
                            # Ensure container can accept addition
                            if isinstance(container, set):
                                container.add(cleaned)
                            elif isinstance(container, list):
                                container.append(cleaned)
                            else:
