def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        return None, None

    # If seq already has a sequence‑like interface, return it unchanged.
    # A sequence is considered to be any object that implements __len__ and __getitem__.
    # This covers lists, tuples, strings, bytes, bytearrays, and range objects.
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return seq, type(seq)

    # At this point seq is assumed to be an iterable that is not a sequence.
    # Try to get an iterator; raise a TypeError if it fails.
    try:
        it = iter(seq)
    except TypeError as exc:
        raise TypeError(f"Object {seq!r} is not iterable") from exc

    # If a buffer size is supplied, collect at most that many items.
    # Otherwise, collect the entire iterable into a list.
    if bufsize is not None:
        buffer = []
        for i, item in enumerate(it):
            if i >= bufsize:
                break
            buffer.append(item)
        return buffer, type(seq)
    else:
        # Gather all items into a list
        return list(it), type(seq)

