def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`."""
    # Default to bin content if no value-making function supplied
    if make_value is None:
        make_value = lambda c: c

    # Map get_coordinate to a lambda over a bin
    coord_funcs = {
        "left":   lambda bin_: bin_.left,
        "right":  lambda bin_: bin_.right,
        "middle": lambda bin_: (bin_.left + bin_.right) / 2.0,
    }
    if get_coordinate not in coord_funcs:
        raise ValueError(f"Unsupported get_coordinate: {get_coordinate!r}")

    get_x = coord_funcs[get_coordinate]

    # Determine graph scale
    if scale is True:
        # Assume histogram has a scale attribute
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Build list of points
    points = []
    for bin_ in hist.bins:
        x = get_x(bin_)

        # Grab content (which may be a numeric value or a context/tuple)
        if hasattr(bin_, "value"):
            content = bin_.value
        else:
            content = bin_

        y_vals = make_value(content)
        # Ensure y_vals is tuple-like
        if not isinstance(y_vals, (list, tuple)):
            y_vals = (y_vals,)

        # Validate field name count
        if len(field_names) != len(y_vals):
            raise ValueError(
                f"make_value returned {len(y_vals)} values but field_names "
                f"has {len(field_names)} fields"
            )

        points.append((x, *y_vals))

    # Create a graph object
    try:
        graph = Graph()
    except NameError:
        # Fallback if Graph class is not defined
        class Graph(list):
            def __init__(self, field_names=None, scale=None):
                super().__init__()
                self.field_names = field_names or []
                self.scale = scale

            def add_point(self, *coords):
                self.append(coords)

        graph = Graph(field_names=field_names, scale=scale_val)

    # Add points to the graph
    for pt in points:
        graph.add_point(*pt)

    return graph

