def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid, providedBy

    errors = []

    # 1. Check interface claim if not tentative
    if not tentative:
        if not providedBy(candidate, iface):
            errors.append(f"{candidate!r} does not provide interface {iface!r}")

    # Helper to determine whether an object is a method on the interface
    def is_interface_method(name, obj):
        return callable(obj) and not name.startswith("_")

    # Helper to determine whether an object is an attribute on the interface
    def is_interface_attribute(name, obj):
        return (not callable(obj)) and not name.startswith("_")

    # 2. Iterate over interface definition
    for name, value in iface.__dict__.items():
        if is_interface_method(name, value):
            # Ensure the candidate has the method
            cand_method = getattr(candidate, name, None)
            if cand_method is None or not callable(cand_method):
                errors.append(f"{candidate!r} does not implement method '{name}' required by {iface!r}")
                continue

            # Compare signatures if possible
            try:
                iface_sig = inspect.signature(value)
            except ValueError:
                iface_sig = None
            try:
                # For bound methods we need the unbound function
                if hasattr(cand_method, "__func__"):  # bound method
                    cand_func = cand_method.__func__
                else:
                    cand_func = cand_method
                cand_sig = inspect.signature(cand_func)
            except ValueError:
                cand_sig = None

            if iface_sig and cand_sig:
                # Compare parameters (excluding 'self')
                iface_params = list(iface_sig.parameters.values())
                cand_params = list(cand_sig.parameters.values())

                # Remove 'self' from candidate params if it is a method
                if cand_params and cand_params[0].name == 'self':
                    cand_params = cand_params[1:]

                # Remove 'self' from interface params if present
                if iface_params and iface_params[0].name == 'self':
                    iface_params = iface_params[1:]

                if len(iface_params) != len(cand_params):
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"interface expects {len(iface_params)} params, "
                        f"candidate provides {len(cand_params)} params."
                    )
                else:
                    # check parameter names and kinds
                    for ip, cp in zip(iface_params, cand_params):
                        if ip.kind != cp.kind or ip.name != cp.name:
                            errors.append(
                                f"Signature mismatch for method '{name}': "
                                f"parameter '{ip.name}' differs."
                            )
                            break

        elif is_interface_attribute(name, value):
            # Ensure the attribute exists on candidate
            if not hasattr(candidate, name):
                errors.append(
                    f"{candidate!r} does not define attribute '{name}' required by {iface!r}"
                )

    # 3. Raise if errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface verification errors: " + "; ".join(errors))

    return True

