def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.
    """
    import re
    import datetime
    from dateutil.tz import tzutc, tzoffset

    # Helper functions
    def parse_date_part(dp):
        # Remove dashes
        dp_clean = dp.replace('-', '')
        # Week format detection
        w_match = re.search(r'(W|w)', dp_clean, re.IGNORECASE)
        if w_match:
            # ISO week date
            parts = re.split(r'(W|w)', dp_clean, maxsplit=1)
            year_str, rel = parts[0], parts[1] if len(parts) > 1 else ''
            # The part after 'W' may contain weekday
            year = int(year_str)
            week_part = rel
            if len(week_part) == 0:
                raise ValueError(f"Missing week number in ISO week date: {dp}")
            if len(week_part) >= 2:
                week = int(week_part[:2])
                if len(week_part) == 3:
                    weekday = int(week_part[2])
                else:
                    weekday = 1  # default Monday
            else:
                raise ValueError(f"Incomplete week number: {dp}")
            # Convert ISO week to calendar date
            # Use datetime.date.fromisocalendar (Python 3.8+)
            try:
                d = datetime.date.fromisocalendar(year, week, weekday)
            except ValueError as e:
                raise ValueError(f"Invalid ISO week date: {dp}") from e
            return d
        else:
            # Regular date
            if len(dp_clean) == 4:
                year = int(dp_clean)
                month = 1
                day = 1
            elif len(dp_clean) == 6:
                year = int(dp_clean[:4])
                month = int(dp_clean[4:6])
                day = 1
            elif len(dp_clean) == 8:
                year = int(dp_clean[:4])
                month = int(dp_clean[4:6])
                day = int(dp_clean[6:8])
            else:
                raise ValueError(f"Unsupported date format: {dp}")
            try:
                return datetime.date(year, month, day)
            except ValueError as e:
                raise ValueError(f"Invalid date: {dp}") from e

