def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # 1. Check for a public Diaspora message indicator in headers
    try:
        if isinstance(request.headers, dict):
            if request.headers.get("X-Diaspora-Public", "").lower() in ("true", "1", "yes"):
                return True
    except Exception:
        pass

    # 2. Check for a private Diaspora message indicator in headers
    try:
        if isinstance(request.headers, dict):
            if request.headers.get("X-Diaspora-Private", "").lower() in ("true", "1", "yes"):
                return True
    except Exception:
        pass

    # 3. Check for legacy payload structure in the request body
    try:
        body = request.body
        if isinstance(body, (bytes, bytearray)):
            body_text = body.decode(errors="ignore")
        else:
            body_text = str(body)
        if body_text:
            # Attempt to parse JSON if applicable
            import json
            payload = json.loads(body_text) if body_text.strip().startswith("{") else {}
            # Legacy payload might contain a specific key or marker
            if isinstance(payload, dict) and "diaspora_legacy" in payload:
                return True
            # Or legacy could be signaled by a specific format string
            if "legacy_payload" in body_text.lower():
                return True
    except Exception:
        pass

    # If none of the checks succeeded, it is not a Diaspora request
    return False

