def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively
    processed.  If a tag appears more than once, its value will be a list
    containing all matching child nodes.
    """
    result = {}
    for child in node:
        # Skip text-only nodes or processing instructions
        if not isinstance(child, object):
            continue
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

