def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure it has the expected structure; if not, return as is
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Attempt XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        # XRD namespace may be present; remove-it for easier access
        ns = {'xrd': root.tag.split('}')[0].strip('{') if '}' in root.tag else ''}
        subject_elem = root.find('Subject', ns) if ns else root.find('Subject')
        subject = subject_elem.text.strip() if subject_elem is not None else None

        links = []
        for link in root.findall('Link', ns) if ns else root.findall('Link'):
            attrs = link.attrib
            # Ensure keys are lowercase for consistency
            link_info = {k.lower(): v for k, v in attrs.items()}
            # The Name attribute might be used as type for display name in some XRDs
            if 'type' not in link_info and 'name' in link_info:
                link_info['type'] = link_info.pop('name')
            links.append(link_info)

        return {
            'subject': subject,
            'links': links,
        }
    except Exception as exc:
        # If both parsing attempts fail, raise a ValueError
        raise ValueError(f"Unable to parse Diaspora webfinger document: {exc}")

