def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        raise ValueError("Host must be provided")

    # Build URL: ensure we use HTTPS and the well-known path.
    if host.startswith(("http://", "https://")):
        base = host.rstrip("/")
    else:
        base = "https://" + host
    url = f"{base}/.well-known/host-meta"

    try:
        resp = requests.get(url, timeout=5)
        resp.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve host-meta from {url}") from exc

    # Parse the XML into an XRD instance.
    try:
        return XRD(resp.text)
    except Exception as exc:
        raise ValueError(f"Received invalid host-meta XML from {url}") from exc

