def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the command's full specification dictionary.
    # The CLI definition typically stores each command's spec under a
    # mapping like `self._spec_map[command_name]`.
    command_spec = self._spec_map.get(command_name)
    if command_spec is None:
        return None
    # Options are usually stored under an "options" key in the command
    # specification. The exact structure can vary, so we attempt to
    # support both a direct dictionary and nested structures.
    options = command_spec.get("options")
    if isinstance(options, dict):
        return options.get(argument_name)
    # Fallback: look for an "arguments" key that might hold option specs
    arguments = command_spec.get("arguments")
    if isinstance(arguments, dict):
        return arguments.get(argument_name)
    # Finally, search recursively within nested dictionaries if necessary.
    for key, value in command_spec.items():
        if isinstance(value, dict) and argument_name in value:
            return value[argument_name]
    # If not found, return None
    return None

