def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return the list of argument names that are required for the specified
    ``command_name`` based on the ``required_when`` condition in ``options_spec``.

    :param command_name: The name of the current command.
    :param options_spec: An iterable of option specification dictionaries.
    :param args: A mapping of argument names to their parsed values.
    :return: A list of argument names that are conditionally required.
    """
    required = []

    for opt in options_spec:
        # Extract the argument name and condition
        name = opt.get("name")
        if not name:
            continue

        cond = opt.get("required_when")
        if not cond:
            continue

        # Handle a dictionary based condition
        if isinstance(cond, dict):
            # If the condition matches the command name directly
            if cond.get("command") == command_name:
                required.append(name)
                continue

            # If the condition references another argument's value
            if "arg" in cond and "values" in cond:
                arg_val = args.get(cond["arg"])
                if arg_val in cond["values"]:
                    required.append(name)
                    continue

        # The condition can also be a callable returning a boolean
        elif callable(cond):
            try:
                if cond(command_name, args):
                    required.append(name)
            except Exception:
                # If we cannot evaluate the callable, skip it
                pass

    return required

