def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import glob

    # Locate a JSON spec file (e.g., spec.json, plugin.json, or any .json file)
    spec_path = None
    for pattern in ("spec.json", "plugin.json", "*.json"):
        files = glob.glob(os.path.join(plugin_dir, pattern))
        if files:
            spec_path = files[0]
            break

    if not spec_path:
        return {}

    # Read and parse the spec file
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}

    # Recursive helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key, sep=sep))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec)

